const B64_UPLOAD = "";
const B64_DOWNLOAD = "";

function b64toBytes(s) {
  const bin = atob(s);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

const uploadBytes = b64toBytes(B64_UPLOAD);
const downloadBytes = b64toBytes(B64_DOWNLOAD);
const ROOM_RE = /^\/[A-Za-z0-9_-]{8}$/;

function htmlPage(bytes) {
  const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream("gzip"));
  return new Response(stream, { headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store" } });
}

function jsonResponse(r) {
  const ct = r.headers.get("Content-Type") || "application/json";
  return new Response(r.body, { status: r.status, headers: { "Content-Type": ct, "Cache-Control": "no-store" } });
}

function jsonError(msg, status) {
  return new Response(JSON.stringify({ error: msg }), { status, headers: { "Content-Type": "application/json", "Cache-Control": "no-store" } });
}

function jsonOk(data) {
  return new Response(JSON.stringify(data), { status: 200, headers: { "Content-Type": "application/json", "Cache-Control": "no-store" } });
}

const BROWSER_HEADERS = {
  "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36",
  "Accept": "application/json, text/plain, */*",
  "Accept-Language": "en-US,en;q=0.9",
  "Referer": "https://file.kiwi/",
  "Sec-Fetch-Dest": "empty",
  "Sec-Fetch-Mode": "cors",
  "Sec-Fetch-Site": "same-origin"
};

async function proxyDlUrl(body) {
  return fetch("https://file.kiwi/api/getdlurl", {
    method: "POST",
    headers: { "Content-Type": "application/json", ...BROWSER_HEADERS },
    body: JSON.stringify(body)
  });
}

const RATE_WINDOW_MS = 60000;
const RATE_LIMITS = {
  files: { perIp: 15, global: 300 },
  dlurl: { perIp: 30, global: 600 },
  chunk: { perIp: 240, global: 6000 },
  manifest: { perIp: 10, global: 100 },
  thumb: { perIp: 60, global: 1200 },
  code: { perIp: 10, global: 100 }
};
const rateHits = new Map();

function rateLimit(key, limit, now) {
  let arr = rateHits.get(key);
  if (!arr) { arr = []; rateHits.set(key, arr); }
  while (arr.length > 0 && now - arr[0] > RATE_WINDOW_MS) arr.shift();
  if (arr.length >= limit) return false;
  arr.push(now);
  return true;
}

function checkRate(p, ip) {
  const cfg = RATE_LIMITS[p.slice("/_proxy/".length)];
  if (!cfg) return true;
  if (rateHits.size > 5000) {
    for (const [k, v] of rateHits) if (v.length === 0) rateHits.delete(k);
  }
  const now = Date.now();
  return rateLimit("g:" + p, cfg.global, now) && rateLimit("i:" + ip + ":" + p, cfg.perIp, now);
}

/* ---------- Admin helpers ---------- */

function verifyAdmin(request, env) {
  const token = request.headers.get("X-Admin-Token");
  return token && token === env.ADMIN_TOKEN;
}

function isAdminRequest(request, env) {
  return request.headers.get("X-Admin-Token") === env.ADMIN_TOKEN;
}

function isPausedPage(url) {
  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Quickdrop — Paused</title>
<style>
  *{margin:0;padding:0;box-sizing:border-box}
  body{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;background:#09090b;color:#fafafa;
    min-height:100vh;display:flex;align-items:center;justify-content:center;text-align:center;padding:20px}
  .c{max-width:400px}.c h1{font-size:1.8rem;margin-bottom:12px;letter-spacing:-0.03em}
  .c p{color:#a1a1aa;font-size:0.95rem;line-height:1.5}
  .dot{width:14px;height:14px;border-radius:50%;background:#f43f5e;display:inline-block;margin-bottom:16px;
    animation:pulse 2s ease-in-out infinite}
  @keyframes pulse{0%,100%{opacity:1}50%{opacity:0.3}}
</style>
</head>
<body><div class="c"><div class="dot"></div><h1>Quickdrop is paused</h1>
<p>This service is temporarily unavailable. Please try again later.</p></div></body></html>`;
}

/* ---------- FCM push ---------- */

async function getFcmAccessToken(creds) {
  const now = Math.floor(Date.now() / 1000);
  const header = { alg: "RS256", typ: "JWT" };
  const claim = {
    iss: creds.client_email,
    scope: "https://www.googleapis.com/auth/firebase.messaging",
    aud: "https://oauth2.googleapis.com/token",
    exp: now + 3600,
    iat: now
  };
  const enc = (obj) => btoa(JSON.stringify(obj)).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
  const signingInput = enc(header) + "." + enc(claim);
  const key = await crypto.subtle.importKey(
    "pkcs8", pemToDer(creds.private_key),
    { name: "RSASSA-PKCS1-v1_5", hash: "SHA-256" }, false, ["sign"]
  );
  const sig = await crypto.subtle.sign("RSASSA-PKCS1-v1_5", key, new TextEncoder().encode(signingInput));
  return signingInput + "." + btoa(String.fromCharCode(...new Uint8Array(sig))).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

function pemToDer(pem) {
  const b64 = pem.replace(/-----BEGIN PRIVATE KEY-----/, "").replace(/-----END PRIVATE KEY-----/, "").replace(/\s+/g, "");
  const bin = atob(b64);
  return Uint8Array.from(bin, c => c.charCodeAt(0));
}

async function sendFcmPush(creds, token, title, body, projectId) {
  try {
    const accessToken = await getFcmAccessToken(creds);
    const msg = {
      message: {
        token: token,
        notification: { title, body },
        android: { priority: "high", notification: { channel_id: "site_alerts", priority: "HIGH" } }
      }
    };
    const res = await fetch(`https://fcm.googleapis.com/v1/projects/${projectId}/messages:send`, {
      method: "POST",
      headers: { "Authorization": "Bearer " + accessToken, "Content-Type": "application/json" },
      body: JSON.stringify(msg)
    });
    if (!res.ok) {
      const err = await res.text();
      return { ok: false, error: err };
    }
    return { ok: true };
  } catch (e) {
    return { ok: false, error: e.message };
  }
}

/* ---------- Monitor ---------- */

async function checkSite(url) {
  const start = Date.now();
  try {
    const r = await fetch(url, { method: "HEAD", redirect: "follow", signal: AbortSignal.timeout(10000) });
    return { online: r.status >= 200 && r.status < 400, responseTime: Date.now() - start };
  } catch (e) {
    return { online: false, responseTime: Date.now() - start, error: e.message };
  }
}

async function runMonitor(env, ctx) {
  const sites = [
    { name: "quickdrop", url: "https://quickdrop.pvlm.site" },
    { name: "filekiwi", url: "https://file.kiwi" }
  ];
  const results = {};
  const prevJson = await env.QDROP.get("monitor_status");
  const prev = prevJson ? JSON.parse(prevJson) : {};

  for (const site of sites) {
    const result = await checkSite(site.url);
    results[site.name] = { ...result, lastChecked: Date.now() };

    const wasOnline = prev[site.name]?.online;
    const wasSlow = prev[site.name]?.responseTime > 5000;
    const nowSlow = result.responseTime > 5000;

    let shouldNotify = false;
    let msg = "";

    if (wasOnline && !result.online) {
      shouldNotify = true;
      msg = `${site.name} is OFFLINE!`;
    } else if (!wasOnline && result.online) {
      shouldNotify = true;
      msg = `${site.name} is back ONLINE`;
    } else if (!wasSlow && nowSlow) {
      shouldNotify = true;
      msg = `${site.name} is slow: ${result.responseTime}ms`;
    } else if (wasSlow && !nowSlow) {
      shouldNotify = true;
      msg = `${site.name} speed recovered: ${result.responseTime}ms`;
    }

    if (shouldNotify && env.ADMIN_TOKEN) {
      try {
        const creds = JSON.parse(env.FCM_CREDENTIALS || "{}");
        const tokensJson = await env.QDROP.get("fcm_tokens");
        if (creds.client_email && tokensJson) {
          const tokens = JSON.parse(tokensJson);
          for (const t of tokens) {
            await sendFcmPush(creds, t, shouldNotify ? "⚠ Quickdrop Alert" : "✅ Quickdrop Status", msg, creds.project_id);
          }
        }
      } catch (e) { /* ignore push errors */ }
    }
  }

  await env.QDROP.put("monitor_status", JSON.stringify(results), { expirationTtl: 300 });
}

/* ---------- Usage analytics (Cloudflare GraphQL) ---------- */

let usageCache = null;
let usageCacheTime = 0;
const USAGE_CACHE_TTL = 60000;

const WORKERS_USAGE_QUERY = `query WorkersUsage($accountTag: String!, $start: Time!, $end: Time!) {
  viewer {
    accounts(filter: {accountTag: $accountTag}) {
      workersInvocationsAdaptive(
        limit: 5000
        filter: {datetime_geq: $start, datetime_leq: $end}
        orderBy: [datetime_ASC]
      ) {
        dimensions { datetime scriptName }
        sum { requests errors wallTime }
        max { cpuTime }
      }
    }
  }
}`;

const KV_USAGE_QUERY = `query KVUsage($accountTag: String!, $start: Time!, $end: Time!) {
  viewer {
    accounts(filter: {accountTag: $accountTag}) {
      kvStorageAnalyticsAdaptiveGroups(
        limit: 100
        filter: {datetime_geq: $start, datetime_leq: $end}
      ) {
        sum { readRequests writeRequests readBytes writeBytes }
        max { storedBytes }
      }
    }
  }
}`;

async function cfGraphql(query, variables, token) {
  const r = await fetch("https://api.cloudflare.com/client/v4/graphql", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "Authorization": "Bearer " + token
    },
    body: JSON.stringify({ query, variables })
  });
  if (!r.ok) throw new Error("GraphQL HTTP " + r.status);
  const json = await r.json();
  if (json.errors) throw new Error(json.errors[0].message);
  return json.data;
}

async function computeUsage(env) {
  const now = Date.now();
  if (usageCache && now - usageCacheTime < USAGE_CACHE_TTL) {
    return usageCache;
  }

  const token = env.CF_ANALYTICS_TOKEN;
  const accountId = env.CF_ACCOUNT_ID;
  if (!token || !accountId) return null;

  try {
    const end = new Date().toISOString();
    const start = new Date(now - 30 * 86400000).toISOString();
    const todayStart = new Date();
    todayStart.setUTCHours(0, 0, 0, 0);
    const todayStr = todayStart.toISOString();

    const [workersData, kvData] = await Promise.all([
      cfGraphql(WORKERS_USAGE_QUERY, { accountTag: accountId, start, end }, token).catch(() => null),
      cfGraphql(KV_USAGE_QUERY, { accountTag: accountId, start, end }, token).catch(() => null)
    ]);

    let todayReqs = 0, todayErrors = 0;
    let periodReqs = 0, periodErrors = 0;
    const byScript = {};

    if (workersData?.viewer?.accounts?.[0]) {
      const acct = workersData.viewer.accounts[0];
      const groups = acct.workersInvocationsAdaptive || [];
      for (const g of groups) {
        const script = g.dimensions.scriptName === "__unknown__" ? "quickdrop" : (g.dimensions.scriptName || "unknown");
        const dt = g.dimensions.datetime;
        const reqs = g.sum.requests || 0;
        const errs = g.sum.errors || 0;
        const wallNs = g.sum.wallTime || 0;
        const cpuNs = g.max?.cpuTime || 0;

        periodReqs += reqs;
        periodErrors += errs;

        if (dt && dt >= todayStr) {
          todayReqs += reqs;
          todayErrors += errs;
        }

        if (!byScript[script]) byScript[script] = { requests: 0, errors: 0, wallTimeMs: 0, cpuMaxMs: 0 };
        byScript[script].requests += reqs;
        byScript[script].errors += errs;
        byScript[script].wallTimeMs += Math.round(wallNs / 1e6);
        if (cpuNs > byScript[script].cpuMaxMs * 1e6) byScript[script].cpuMaxMs = Math.round(cpuNs / 1e6);
      }
    }

    let kv = {};
    if (kvData?.viewer?.accounts?.[0]) {
      const kvGroups = kvData.viewer.accounts[0].kvStorageAnalyticsAdaptiveGroups || [];
      let reads = 0, writes = 0, storedBytes = 0;
      for (const g of kvGroups) {
        reads += g.sum.readRequests || 0;
        writes += g.sum.writeRequests || 0;
        if (g.max.storedBytes > storedBytes) storedBytes = g.max.storedBytes;
      }
      kv = { readRequests: reads, writeRequests: writes, storedBytes };
    }

    const result = {
      today: { requests: todayReqs, errors: todayErrors },
      period: { requests: periodReqs, errors: periodErrors },
      byScript,
      kv,
      limits: { freeRequestsPerDay: 100000 }
    };

    usageCache = result;
    usageCacheTime = now;
    return result;
  } catch (e) {
    return null;
  }
}

async function getUsage(env, ctx) {
  const usage = await computeUsage(env);
  if (!usage) return jsonError("Analytics not configured or unavailable", 500);
  return jsonOk(usage);
}

/* ---------- Main ---------- */

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);

    // Production sits behind Cloudflare's TLS terminator, so plain http should
    // bounce to https. Two cases must NOT bounce, or it loops forever:
//   - `wrangler dev` serves http only and has no cert, so skip it for
    //     loopback and private LAN addresses.
//   - A TLS-terminating proxy (cloudflared tunnel) hands us http while the
    //     visitor is already on https; X-Forwarded-Proto tells us that.
    const host = url.hostname;
    const isLocalDev = host === "127.0.0.1" || host === "localhost" ||
      host === "::1" || host === "0.0.0.0" ||
      /^10\./.test(host) || /^192\.168\./.test(host) ||
      /^172\.(1[6-9]|2\d|3[01])\./.test(host) || /^169\.254\./.test(host);
    const forwardedProto = request.headers.get("X-Forwarded-Proto");
    const alreadyHttps = forwardedProto === "https";
    if (url.protocol === 'http:' && !isLocalDev && !alreadyHttps) {
      url.protocol = 'https:';
      return Response.redirect(url.toString(), 301);
    }

    const p = url.pathname;

    /* --- Admin API --- */
    if (p.startsWith("/_admin")) {
      if (!verifyAdmin(request, env)) return jsonError("Unauthorized", 401);

      if (p === "/_admin/status") {
        const statusJson = await env.QDROP.get("monitor_status");
        const paused = await env.QDROP.get("paused");
        const tokensJson = await env.QDROP.get("fcm_tokens");
        const usage = await computeUsage(env);
        return jsonOk({
          paused: paused === "true",
          sites: statusJson ? JSON.parse(statusJson) : {},
          fcmTokens: tokensJson ? JSON.parse(tokensJson).length : 0,
          usage
        });
      }

      if (p === "/_admin/pause" && request.method === "POST") {
        const body = await request.json();
        await env.QDROP.put("paused", body.paused ? "true" : "false");
        return jsonOk({ paused: body.paused });
      }

      if (p === "/_admin/token" && request.method === "POST") {
        const body = await request.json();
        const tokensJson = await env.QDROP.get("fcm_tokens");
        const tokens = tokensJson ? JSON.parse(tokensJson) : [];
        if (body.token && !tokens.includes(body.token)) {
          tokens.push(body.token);
          await env.QDROP.put("fcm_tokens", JSON.stringify(tokens));
        }
        return jsonOk({ count: tokens.length });
      }

      if (p === "/_admin/test-notif" && request.method === "POST") {
        const body = await request.json().catch(() => ({}));
        try {
          const creds = JSON.parse(env.FCM_CREDENTIALS || "{}");
          const tokensJson = await env.QDROP.get("fcm_tokens");
          if (!creds.client_email) return jsonError("FCM credentials not configured", 500);
          if (!tokensJson) return jsonError("No FCM tokens registered", 400);
          const tokens = JSON.parse(tokensJson);
          let sent = 0;
          for (const t of tokens) {
            const r = await sendFcmPush(creds, t, body.title || "Test Notification", body.body || "This is a test notification from PVLM Admin", creds.project_id);
            if (r.ok) sent++;
          }
          return jsonOk({ sent, total: tokens.length });
        } catch (e) {
          return jsonError("Push failed: " + e.message, 500);
        }
      }

      if (p === "/_admin/monitor" && request.method === "POST") {
        await runMonitor(env, ctx);
        return jsonOk({ ran: true });
      }

      if (p === "/_admin/usage") {
        return await getUsage(env, ctx);
      }

      return jsonError("Unknown admin endpoint", 404);
    }

    /* --- Pause check --- */
    const paused = await env.QDROP.get("paused");
    if (paused === "true" && !isAdminRequest(request, env)) {
      return new Response(isPausedPage(url), {
        headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store" },
        status: 503
      });
    }

    /* --- Rate limiting --- */
    if (p.startsWith("/_proxy/")) {
      const ip = request.headers.get("CF-Connecting-IP") || "0.0.0.0";
      if (!checkRate(p, ip)) {
        return jsonError("Too many requests — please slow down and try again in a minute.", 429);
      }
    }

    /* --- Pages --- */
    if (p === "/" || p === "/index.html") return htmlPage(uploadBytes);
    if (p === "/download" || p === "/download.html") return htmlPage(downloadBytes);
    if (ROOM_RE.test(p)) return htmlPage(downloadBytes);

    /* --- Short code redirect: /c/123456 --- */
    const codeMatch = p.match(/^\/c\/(\d{6})$/);
    if (codeMatch) {
      const code = codeMatch[1];
      const data = await env.QDROP.get("code:" + code, { type: "json" });
      if (!data) return new Response("Code expired or not found.", { status: 404, headers: { "Content-Type": "text/html; charset=utf-8" } });
      return Response.redirect(url.origin + "/download.html?roomid=" + encodeURIComponent(data.roomId) + "#" + encodeURIComponent(data.key), 302);
    }

    /* --- Proxy APIs --- */
    if (p === "/_proxy/files") {
      const roomid = url.searchParams.get("roomid");
      if (!roomid) return jsonError("roomid missing", 400);
      const r = await fetch("https://file.kiwi/api/files/list?roomid=" + encodeURIComponent(roomid) + "&offset=0&limit=1000", { headers: BROWSER_HEADERS });
      return jsonResponse(r);
    }

    if (p === "/_proxy/dlurl") {
      let body;
      try { body = await request.json(); } catch { return jsonError("invalid JSON", 400); }
      return jsonResponse(await proxyDlUrl(body));
    }

    if (p === "/_proxy/create" && request.method === "POST") {
      let body;
      try { body = await request.json(); } catch { return jsonError("invalid JSON", 400); }
      const r = await fetch("https://api.file.kiwi/v2/folders", {
        method: "POST",
        headers: { "Content-Type": "application/json", ...BROWSER_HEADERS },
        body: JSON.stringify(body)
      });
      return jsonResponse(r);
    }

    if (p === "/_proxy/verify") {
      const sp = url.searchParams;
      const folderId = sp.get("folderId");
      const fileId = sp.get("fileId");
      const uploadAuth = sp.get("uploadAuth");
      if (!folderId || !fileId || !uploadAuth) return jsonError("missing params", 400);
      const r = await fetch("https://api.file.kiwi/v2/folders/" + encodeURIComponent(folderId) + "/files/" + encodeURIComponent(fileId) + "/upload-status?uploadAuth=" + encodeURIComponent(uploadAuth), { headers: BROWSER_HEADERS });
      return jsonResponse(r);
    }

    if (p === "/_proxy/chunk") {
      const sp = url.searchParams;
      const chunk = parseInt(sp.get("chunk") || "0", 10);
      const body = {
        sname: sp.get("sname") || "cf",
        usepoint: null,
        chunks: parseInt(sp.get("chunks") || "1", 10),
        chunk: chunk,
        id: sp.get("id") || "",
        idf: sp.get("fid") || "",
        dd: sp.get("dd") || ""
      };
      const r = await proxyDlUrl(body);
      if (!r.ok) return jsonResponse(r);
      const j = await r.json();
      if (!j.dlist || !j.dlist[0] || !j.dntail || !j.head) {
        return jsonError(j.alert || j.error || "no download url", 502);
      }
      const chunkNum = String(chunk + 1).padStart(5, "0");
      const chunkUrl = j.head + "/" + chunkNum + "?X-Amz-Signature=" + j.dlist[0] + "&" + j.dntail;
      const fr = await fetch(chunkUrl);
      return new Response(fr.body, { status: fr.status, headers: { "Content-Type": "application/octet-stream", "Cache-Control": "no-store" } });
    }

    /* --- Stream endpoint: returns signed URL info, client fetches chunks via /_proxy/chunk in parallel --- */
    if (p === "/_proxy/stream") {
      const sp = url.searchParams;
      const totalChunks = parseInt(sp.get("chunks") || "1", 10);
      const filesize = parseInt(sp.get("filesize") || "0", 10);
      const CHUNK_SIZE = 10485760; // 10MB default chunk size

      // Step 1: Fetch the signed download URL ONCE
      const body = {
        sname: sp.get("sname") || "cf",
        usepoint: null,
        chunks: totalChunks,
        chunk: 0,
        id: sp.get("id") || "",
        idf: sp.get("fid") || "",
        dd: sp.get("dd") || ""
      };
      const r = await proxyDlUrl(body);
      if (!r.ok) {
        try { const err = await r.json(); return jsonError(err.alert || err.error || "download URL failed", r.status); }
        catch { return jsonError("download URL failed (HTTP " + r.status + ")", r.status); }
      }
      const j = await r.json();
      if (!j.dlist || !j.dlist[0] || !j.dntail || !j.head) {
        return jsonError(j.alert || j.error || "no download url", 502);
      }
      return jsonResponse({ head: j.head, dlist: j.dlist, dntail: j.dntail, chunks: totalChunks, filesize: filesize });
    }

    /* --- Manifest: store/fetch multi-room mappings --- */
    if (p === "/_proxy/manifest") {
      const sp = url.searchParams;
      const roomId = sp.get("roomId");
      if (!roomId) return jsonError("roomId missing", 400);

      if (request.method === "POST") {
        let body;
        try { body = await request.json(); } catch { return jsonError("invalid JSON", 400); }
        if (!body.rooms || !Array.isArray(body.rooms)) return jsonError("rooms array required", 400);
        const ttl = body.ttl || 324000;

        // Append mode is what makes a shared folder work: file.kiwi has no
        // endpoint for adding files to an existing folder, so each person
        // uploads into their own folder and we merge those folders under one
        // anchor room id. Append dedupes on roomId so retries are harmless.
        let rooms = body.rooms;
        // `shared` marks this as a two-way folder so download.html can offer to
        // add files. Once shared it stays shared, so a contributor appending to
        // someone else's folder can't accidentally clear the flag.
        let shared = !!body.shared;
        if (body.append || Array.isArray(body.remove)) {
          const prev = await env.DB.prepare("SELECT data FROM manifests WHERE room_id = ?").bind(roomId).first();
          const seen = new Map();
          if (prev) {
            try {
              const parsed = JSON.parse(prev.data);
              const existing = parsed.rooms || [];
              if (parsed.shared) shared = true;
              for (const r of existing) {
                if (r && (r.roomId || r.folderId)) seen.set(r.roomId || r.folderId, r);
              }
            } catch (e) { /* treat unparseable as empty */ }
          }
          if (body.append) {
            for (const r of body.rooms) {
              if (r && (r.roomId || r.folderId)) seen.set(r.roomId || r.folderId, r);
            }
          }
          if (Array.isArray(body.remove)) {
            // file.kiwi's v2 API has no delete endpoint, so removing a file means
            // dropping its room from the manifest: it disappears from the shared
            // folder for everyone, but the ciphertext stays on their servers
            // until the normal auto-delete.
            for (const gone of body.remove) seen.delete(gone);
          }
          rooms = [...seen.values()];
        }

        const expires = Math.floor(Date.now() / 1000) + ttl;
        await env.DB.prepare("INSERT OR REPLACE INTO manifests (room_id, data, created_at, expires_at) VALUES (?, ?, unixepoch(), ?)").bind(roomId, JSON.stringify({ rooms, shared }), expires).run();
        return jsonOk({ stored: true, count: rooms.length, shared });
      }

      const row = await env.DB.prepare("SELECT data FROM manifests WHERE room_id = ? AND expires_at > unixepoch()").bind(roomId).first();
      if (!row) return new Response(JSON.stringify({ rooms: [{ roomId: roomId, key: sp.get("key") || "" }] }), { headers: { "Content-Type": "application/json", "Cache-Control": "no-store" } });
      try { return new Response(row.data, { headers: { "Content-Type": "application/json", "Cache-Control": "no-store" } }); }
      catch { return new Response(JSON.stringify({ rooms: [{ roomId: roomId, key: sp.get("key") || "" }] }), { headers: { "Content-Type": "application/json", "Cache-Control": "no-store" } }); }
    }

    /* --- Thumbnail: store/fetch video thumbnails from D1 --- */
    if (p === "/_proxy/thumb") {
      const sp = url.searchParams;
      const roomId = sp.get("roomId");
      const fileId = sp.get("fileId");
      if (!roomId || !fileId) return jsonError("roomId and fileId required", 400);

      if (request.method === "POST") {
        const ct = request.headers.get("Content-Type") || "";
        if (ct.includes("application/json")) {
          let body;
          try { body = await request.json(); } catch { return jsonError("invalid JSON", 400); }
          if (!body.data) return jsonError("data field required", 400);
          const ttl = body.ttl || 324000;
          const expires = Math.floor(Date.now() / 1000) + ttl;
          await env.DB.prepare("INSERT OR REPLACE INTO thumbs (room_id, file_id, data, created_at, expires_at) VALUES (?, ?, ?, unixepoch(), ?)").bind(roomId, fileId, body.data, expires).run();
          return jsonOk({ stored: true });
        }
        const ab = await request.arrayBuffer();
        if (ab.byteLength === 0) return jsonError("empty body", 400);
        const ttl = parseInt(sp.get("ttl") || "324000", 10);
        const expires = Math.floor(Date.now() / 1000) + ttl;
        const b64 = btoa(String.fromCharCode(...new Uint8Array(ab)));
        await env.DB.prepare("INSERT OR REPLACE INTO thumbs (room_id, file_id, data, created_at, expires_at) VALUES (?, ?, ?, unixepoch(), ?)").bind(roomId, fileId, b64, expires).run();
        return jsonOk({ stored: true });
      }

      const row = await env.DB.prepare("SELECT data FROM thumbs WHERE room_id = ? AND file_id = ? AND expires_at > unixepoch()").bind(roomId, fileId).first();
      if (!row) return jsonError("not found", 404);
      return new Response(JSON.stringify({ data: row.data }), { headers: { "Content-Type": "application/json", "Cache-Control": "no-store" } });
    }

    /* --- Short code: create or lookup --- */
    if (p === "/_proxy/code") {
      const sp = url.searchParams;

      if (request.method === "OPTIONS") {
        return new Response(null, { status: 204, headers: {
          "Access-Control-Allow-Origin": "*",
          "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
          "Access-Control-Allow-Headers": "Content-Type",
          "Access-Control-Max-Age": "86400"
        }});
      }

      if (request.method === "POST") {
        let body;
        try { body = await request.json(); } catch (e) { return jsonError("invalid JSON", 400); }
        if (!body || !body.roomId || !body.key) return jsonError("roomId and key required", 400);
        const ttl = body.ttl || 324000;
        const expires = Math.floor(Date.now() / 1000) + ttl;
        const code = String(Math.floor(100000 + Math.random() * 900000));
        await env.DB.prepare("INSERT OR REPLACE INTO codes (code, room_id, key, created_at, expires_at) VALUES (?, ?, ?, unixepoch(), ?)").bind(code, body.roomId, body.key, expires).run();
        return new Response(JSON.stringify({ code: code }), { status: 200, headers: { "Content-Type": "application/json", "Cache-Control": "no-store", "Access-Control-Allow-Origin": "*" } });
      }

      const code = sp.get("code");
      if (!code || !/^\d{6}$/.test(code)) return jsonError("valid 6-digit code required", 400);
      const row = await env.DB.prepare("SELECT room_id, key FROM codes WHERE code = ? AND expires_at > unixepoch()").bind(code).first();
      if (!row) return jsonError("code expired or not found", 404);
      return new Response(JSON.stringify({ roomId: row.room_id, key: row.key }), { headers: { "Content-Type": "application/json", "Cache-Control": "no-store", "Access-Control-Allow-Origin": "*" } });
    }

    return new Response("Not found", { status: 404 });
  },

  async scheduled(event, env, ctx) {
    ctx.waitUntil(runMonitor(env, ctx));
    ctx.waitUntil(
      (async () => {
        try {
          await env.DB.batch([
            env.DB.prepare("DELETE FROM manifests WHERE expires_at <= unixepoch()"),
            env.DB.prepare("DELETE FROM thumbs WHERE expires_at <= unixepoch()"),
            env.DB.prepare("DELETE FROM codes WHERE expires_at <= unixepoch()")
          ]);
        } catch (e) {}
      })()
    );
  }
};
